// Go: a goroutine is a stackful coroutine - any function blocks at any depth.
func handle(ctx context.Context, id int) (Result, error) {
    user, err := fetchUser(ctx, id)     // an ordinary call that may block: no async keyword
    if err != nil { return Result{}, err }
    orders, err := fetchOrders(ctx, user)
    if err != nil { return Result{}, err }   // ordinary straight-line error handling
    return Result{user, orders}, nil         // no colour propagation: this is the point
}

go handle(ctx, 1)      // start a coroutine

// communicate with channels, not shared memory (a goroutine may migrate):
ch := make(chan Result, 8)
